head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > validateObject]<br/>컴포넌트에 입력된 값이 유효한 값인지 검사한 후 결과값을 Object 로 반환하는 메소드입니다.",
    "validation" : [
        "mandatory=true 이고 minLength, maxLength, minByteLength, maxByteLength 속성값이 한 개 이상 설정되어 있어야 올바른 결과값을 반환합니다.",
        "입력값에 대한 유효성 체크 결과를 객체로 반환합니다.",
        "반환된 객체의 callerId 속성값으로 유효성 체크 대상 컴포넌트의 렌더링 ID 값을 갖습니다.",
        "반환된 객체의 type 속성값으로 유효성 체크를 통과하지 못한 속성의 이름을 갖습니다.",
        "반환된 객체의 value 값으로 type 으로 전달된 속성에 설정된 값을 갖습니다.",
        "유효성 체크에 성공한 경우 빈 객체를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.check_validateObject = function (target) {
    let rtnObj  = target.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("validateObject : "+ rtnObj);

    if (rtnObj) {
        let callerId = rtnObj.callerId
        let type = rtnObj.type
        let value = rtnObj.value

        wf_body_bottom.getObj("scwin").setReturnValue("callerId : "+ callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : "+ type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : "+ value);
    }
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue(1234);
};


scwin.btn_validateObject1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validateObject(target1);
}


